\label{a14}
\label{1.3Adef}
For a $\lambda$--colouring $F$ we define $\lambda$--colourings $F^\oplus$ and
$F^\otimes$ as follows.
\begin{enumerate}
\item A function $g\in{}^{\textstyle \gamma}({\mathcal H}(\lambda))$ is called
$F^\oplus$--standard if there is a tuple $(T,\bar{f},\bar{\alpha},\bar{A})$
(called a witness) such that 
\begin{enumerate}
\item[(i)] $T\subseteq {}^{\textstyle\omega{>}}\gamma$ is a well founded tree
(so $\langle\rangle\in T$, $\nu\vartriangleleft\eta\in T\ \Rightarrow \nu\in
T$ and $T$ has no $\omega$--branch);
\item[(ii)] $\bar{f}=\langle f_\eta^\ell:\eta\in T,\ \ell\leq k_\eta
\rangle$, where $f_\eta^\ell\in {\rm DOM}(F)\cap{}^{\textstyle\gamma}({\mathcal H}(\lambda))$;
\item[(iii)] $\bar{\alpha}=\langle\alpha_\eta:\eta\in T\rangle$, where
$\alpha_\eta<\lambda$;
\item[(iv)] $\bar{A}=\langle A^\ell_\eta:\eta\in T,\ \ell\leq\ell_\eta
\rangle$, where $A_\eta^\ell\subseteq\alpha_\eta$;
\item[(v)] $g(\beta)=(T\cap{}^{\textstyle\omega{>}}\beta,\langle f_\eta^\ell
{\restriction}\beta:\eta\in T\cap{}^{\textstyle\omega{>}}\beta,\ \ell<k_\eta\rangle,
\langle\alpha_\eta:\eta\in T\cap{}^{\textstyle\omega{>}}\beta\rangle,\langle
A_\eta^\ell:\eta\in T\cap{}^{\textstyle\omega{>}}\beta,\ \ell\leq\ell_\eta
\rangle)$ for each $\beta<\gamma$.
\end{enumerate}
\item ${\rm DOM}(F^\oplus)=\bigcup\limits_{\alpha<\lambda}{}^{\textstyle\alpha}(
{\mathcal H}(\lambda))$ and for $g\in{}^{\textstyle\gamma}({\mathcal H}(\lambda))$:
\begin{enumerate}
\item[$(\oplus)_\alpha$] if $\gamma=0$ then $F^\oplus(g)=0$,
\item[$(\oplus)_\beta$]  if $\gamma>0$ and $g$ is not standard then
$F^\oplus(g)=0$, 
\item[$(\oplus)_\gamma$] if $\gamma>0$ and $g$ is standard as witnessed by
$\langle \bar{T},\bar{f},\bar{\alpha},\bar{A}\rangle$ then $F^\oplus(g)=
{\bf t}^0_{F,g}(\langle\rangle)$, where ${\bf t}^\ell_{F,g}(\eta)\in\{0,1\}$ (for
$\eta\in T$, $\ell=0,1$) are defined by downward induction as follows.
\begin{enumerate}
\item[If] $\eta\in\max(T)$ then ${\bf t}^\ell_{F,g}(\eta)=1$ iff $\gamma\in
A_\eta$,
\item[if] $\eta\in T\setminus\max(T)$, $\gamma<\alpha_\eta$ then
${\bf t}^\ell_{F,g}(\eta)=1$ iff $\gamma\in A_\eta$,
\item[if] $\eta\in T\setminus \max(T)$, $\gamma\geq\alpha_\eta$ then
\[\begin{array}{lcl}
{\bf t}^1_{F,g}(\eta)=1& \mbox{ iff }& F(f_\eta)=1\ \mbox{ or }\ (\exists i<
\gamma)({\bf t}^1_{F,g}(\eta{}^\frown\!\langle i\rangle)=1),\\
{\bf t}^0_{F,g}(\eta)=1& \mbox{ iff }& (\exists i<\gamma)({\bf t}^0_{F,g}(\eta{}^\frown\!
\langle i\rangle)=1)\ \mbox{ or}\\
& & F(f_\eta                       
)=1\ \&\ (\forall i<\gamma)({\bf t}^1_{F,g}(\eta{}^\frown\!\langle i
\rangle)=0).
  \end{array}\]
\end{enumerate}
\end{enumerate}
\item A function $g\in {}^{\textstyle\gamma}({\mathcal H}(\lambda))$ is called
$F^\otimes$--standard if there is a tuple $(T,\bar{f},\bar{\ell},\bar{
\alpha},\bar{A})$ (called a witness) such that 
\begin{enumerate}
\item[(i)] $T\subseteq {}^{\textstyle\omega{>}}\gamma$ is a well founded tree;
\item[(ii)] $\bar{f}=\langle f_\eta:\eta\in T\rangle$, where $f_\eta\in{\rm DOM}(F)
\cap{}^{\textstyle\gamma}({\mathcal H}(\lambda))$;
\item[(iii)] $\bar{\ell}=\langle\ell_\eta:\eta\in T\rangle$, where
$\ell_\eta:{}^{\textstyle 3}\{0,1\}\longrightarrow\{0,1\}$;
\item[(iv)] $\bar{\alpha}=\langle\alpha_\eta:\eta\in T\rangle$, where
$\alpha_\eta<\lambda$;
\item[(v)] $\bar{A}=\langle A_\eta:\eta\in T\rangle$, where $A_\eta\subseteq
\alpha_\eta$;
\item[(vi)] $g(\beta)=(T\cap{}^{\textstyle\omega{>}}\beta,\langle f_\eta{\restriction}
\beta:\eta\in T\cap{}^{\textstyle\omega{>}}\beta\rangle,\langle\ell_\eta:\eta
\in T\cap{}^{\textstyle\omega{>}}\beta\rangle,\langle\alpha_\eta:\eta\in T
\cap{}^{\textstyle\omega{>}}\beta\rangle,\langle A_\eta:\eta\in T
\cap{}^{\textstyle\omega{>}}\beta\rangle)$ for each $\beta<\gamma$.
\end{enumerate}
\item ${\rm DOM}(F^\otimes)=\bigcup\limits_{\alpha<\lambda}{}^{\textstyle\alpha}(
{\mathcal H}(\lambda))$ and for $g\in{}^{\textstyle\gamma}({\mathcal H}(\lambda))$:
\begin{enumerate}
\item[$(\otimes)_\alpha$] if $\gamma=0$ then $F^\otimes(g)=0$,
\item[$(\otimes)_\beta$]  if $\gamma>0$ and $g$ is not $F^\otimes$--standard
then $F^\otimes(g)=0$, 
\item[$(\otimes)_\gamma$] if $\gamma>0$ and $g$ is $F^\otimes$--standard as
witnessed by $\langle \bar{T},\bar{f},\bar{\ell},\bar{\alpha},\bar{A}\rangle$
then $F^\otimes(g)={\bf t}_{F,g}(\langle\rangle)$, where ${\bf t}_{F,g}(\eta)\in\{0,
1\}$ (for $\eta\in T$) are defined by downward induction as follows. 
\begin{enumerate}
\item[If] $\eta\in\max(T)$ then ${\bf t}_{F,g}(\eta)=1$ iff $\gamma\in A_\eta$,
\item[if] $\eta\in T\setminus\max(T)$, $1+\gamma<\alpha_\eta$ then
${\bf t}_{F,g}(\eta)=1$ iff $\gamma\in A_\eta$,
\item[if] $\eta\in T\setminus \max(T)$, $1+\gamma\geq\alpha_\eta$ then
\[{\bf t}_{F,g}(\eta)=\ell_\eta(F(f_\eta),\max\{{\bf t}_{F,g}(\eta{}^\frown\!\langle\beta
\rangle):\beta<\gamma\},\min\{{\bf t}_{F,g}(\eta{}^\frown\!\langle\beta\rangle):
\beta<\gamma\}).\]
\end{enumerate}
\end{enumerate}
\end{enumerate}

\label{a17}
\label{1.3Bclaim}
Let $F$ be a $\lambda$--colouring. Then $F^\oplus$ is a $\lambda$--colouring
and 
\begin{enumerate}
\item[(a)] if $S\in{\rm ID^a}(F)$ then $0_S\cup 1_{\lambda\setminus S}\in{\mathfrak B}(
F^\oplus)$ and ${\mathfrak B}(F)\subseteq{\mathfrak B}(F^\oplus)$,
\item[(b)] ${\rm ID^a}(F)\subseteq{\rm ID}_1(F^\oplus)={\rm ID}_1^-(F^\oplus)={\rm ID^a}(F^\oplus)$, 
\end{enumerate}

\label{a20}
\label{inequality}
Let $F_1,F_2$ be $\lambda$--colourings (with ${\rm DOM}(F_\ell)$ being either
${}^{\textstyle\lambda\!>}2$ or $\bigcup\limits_{\alpha<\lambda}
{}^{\textstyle\alpha}({\mathcal H}(\lambda))$, see \ref{colourings}(1)).
\begin{enumerate}
\item We say that $F_1\leq F_2$ \underline{when}                        
there is $h: {\rm DOM}(F_1) \longrightarrow
{\rm DOM}(F_2)$ such that:                         
\begin{enumerate}
\item[(a)] $\eta\trianglelefteq\nu\quad \Rightarrow\quad h(\eta)
\trianglelefteq h(\nu)$,
\item[(b)] $h(\eta)=\lim\limits_{\alpha<\delta} h(\eta\restriction\alpha)$,
for every $\eta\in {}^{\textstyle\delta}2$, $\delta$ a limit 
ordinal,                      
\item[(c)] $(\forall\eta\in {\rm DOM}(F_1))(0<\ell g\/(\eta)=\ell g\/(h(\eta))\ \Rightarrow
\ F_1(\eta)=F_2(h(\eta)))$. 
\end{enumerate}
\item We say that $F_1\leq^* F_2$ \underline{when}                        
there is $h:{\rm DOM}(F_1)\longrightarrow
{\rm DOM}(F_2)$ such that the clauses (a)--(c) above hold but
\begin{enumerate}
\item[(d)] if $\eta\in{\rm DOM}_\lambda(F_1)$ and $\lim\limits_{\alpha<\lambda}
h(\eta{\restriction}\alpha)$ has length $<\lambda$ then $F_1(\eta{\restriction}\alpha)=0$ for
every large enough $\alpha$.
\end{enumerate}
\end{enumerate}

\label{a23}
\begin{enumerate}
\item $\leq^*$ and $\leq$ are transitive relations on $\lambda$--colourings,
satisfying                      
$\leq^*\ \subseteq\ \leq$. 
\item $\leq$ is $\lambda^+$-directed.
\end{enumerate}

\label{a26}
\label{prop1.8}
\begin{enumerate}
\item For every colouring $F_1:\bigcup\limits_{\alpha<\lambda}{}^{\textstyle
\alpha}({\mathcal H}(\lambda))\longrightarrow 2$ there is a colouring $F_2:
{}^{\textstyle\lambda\!>}2\longrightarrow 2$ such that $F_1\leq F_2\leq^*
F_1$.  
\item For every $\lambda$--colouring $F_2:{}^{\textstyle\lambda{>}}2
\longrightarrow 2$ there is a $\lambda$--colouring $F_1:\bigcup\limits_{
\alpha<\lambda}{}^{\textstyle\alpha}({\mathcal H}(\lambda))
\rightarrow 2                      
$ such that
$F_2\leq F_1\leq^* F_2$.  
\end{enumerate}

\label{a44}
\label{getF}
Assume \ref{tempassu}. Then:
\begin{enumerate}
\item There exists $\eta\in{}^{\textstyle\lambda}2$ such that 
\[\lambda\setminus S_{\alpha^*[\eta]}[\eta]\notin{\rm ID^b}(F^\otimes).\]
\item If $S\in{\mathfrak B}(F^\otimes)\setminus {\rm ID^b}(F^\otimes)$ then we can demand
$S\subseteq S_{\alpha^*[\eta]}[\eta]$.
\end{enumerate}

\label{a44b}
\label{clx}
For each $\alpha$, $S_\alpha\in{\mathfrak B}(F^\otimes)$.

\label{a44d}
\label{cly}
For each $\alpha$, $Y_\alpha\stackrel{\rm def}{=}\{\beta<\lambda:\eta(\beta)
=1\}\cap S_\alpha\in{\mathfrak B}(F^\otimes)$.

\label{a53}
\begin{enumerate}
\item Recall that if $\lambda\notin{{\rm WDmId}_\lambda}$ then $S^*_F\neq\lambda$.
\item  Recall:  ${\rm ID^a}(F^\otimes)                                     
)={{\rm WDmId}_\lambda}(F^\otimes)$ is a
normal ideal and ${\rm ID^b} (F^\otimes )\subseteq {\rm ID^c}(F^\otimes)$ are                         
normal ideals   extending it.                            
\end{enumerate}

\label{b2}
Assume that $\lambda$ is a regular uncountable cardinal and $\mu\leq 2^{<
\lambda}$. Let $F_i: {}^{\textstyle\lambda\!>}2\longrightarrow\{0,1\}$ be
$\lambda$--colourings for $i<\mu$. Then there is a colouring $F:{}^{
\textstyle\lambda>}2\longrightarrow\{0,1\}$ such that $F_i\leq F$ for every
$i<\mu$.

\label{b5c}
\label{cl2}
$\rho$ is a weak diamond sequence for $F^{\rm tr}$ even on $X_0\cup X_1$.

\label{b8}
\label{claim3}
Suppose $F^{\rm tr}$ is a $(\lambda,\theta)$--colouring, $\theta\leq\lambda$ and
$F_i$ (for $i<\theta$) are given by
\[F_i(f)=\left\{\begin{array}{ll}
1&\mbox{if }F(f)=i,\\
0&\mbox{otherwise.}
\end{array}\right.\]
Let $F:{}^{\textstyle\lambda\!>}2\longrightarrow 2$ be such that $(\forall
i<\theta)(F_i\leq F)$ and let $F^\otimes$ be as in \ref{1.3Adef} for $F$. 
Suppose that ${\rm ID^b}(F^\otimes)$ is $\lambda^+$--saturated, and $S^*_{F^\otimes}
\neq\lambda$                                                  
(equivalently $\lambda\notin{\rm ID^c}(F^\otimes)$).

If $ (\otimes )$  then $( \bigstar)  $  \underline{where}:


\begin{enumerate}
\item[$(\otimes)$] there are sets $Y_i\subseteq\lambda\setminus S^*_{
F^\otimes}$ for $i<\theta$ such that 
\begin{enumerate}
\item[(a)] $(\forall i<\theta)(Y_i\notin{\rm ID^b}(F^\otimes))$,
\item[(b)] the sets $Y_i$ are pairwise disjoint or at least 
\[(\forall i<j<\theta)(Y_i\cap Y_j\in{\rm ID^b}(F^\otimes)),\]
\item[(c)] $\bigcap\limits_{i<\theta}\min_{F^\otimes}(Y_i)\notin
{\rm ID^b}(F^\otimes)$, see \ref{con2}(h). 
\end{enumerate}
\end{enumerate}


\begin{enumerate}
\item[$(\bigstar)$] there is a weak diamond sequence $\eta\in {}^{\textstyle
\lambda}\theta$ for $F^{\rm tr}$, i.e.

\[
(\forall f\in {}^{\textstyle\lambda}2)(\{\delta<\lambda: F^{\rm tr}(f{\restriction}
\delta)=\eta(\delta)\} 
   \mbox{ is stationary    and even }   \not=  \emptyset 


  \mod  
  {\rm ID^b}(F^ \otimes ) );
\]
moreover
\[(\forall f\in {}^{\textstyle\lambda}2)(\{\delta<\lambda: F^{\rm tr}(f{\restriction}
\delta)=\eta(\delta)\}\notin{\rm ID^b}(F^\otimes)).\]
\end{enumerate}

\label{b14}
Under the assumptions of \ref{claim3}:  
\begin{enumerate}
\item If $2^\theta<\lambda$ then there is a sequence $\langle Y_i:
i<\theta\rangle$ as required in \ref{claim3}$(\otimes )$                                          
\item Similarly if $\theta\leq\aleph_0$.
\item In both cases, if $S\notin{\rm ID^b}(F^\otimes)$ then we can demand $(\forall
i<\theta)(Y_i\subseteq S)$.
\end{enumerate}
